return ['domain'=>'press-permit-core>= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? 1 : 2);>= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? 1: 2);','plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11 ? 0 : n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? 1 : 2);','language'=>'hr','project-id-version'=>'PublishPress Permissions Free 4.8.2','pot-creation-date'=>'2026-04-22T11:57:22+00:00','po-revision-date'=>'2026-05-26 19:59+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Permissions Free'=>'PublishPress Permissions Free','https://publishpress.com/presspermit'=>'https://publishpress.com/presspermit','PublishPress Permissions allows you to enable or deny access to posts, pages, categories, tags and more.'=>'PublishPress Permissions omogućuje vam omogućavanje ili uskraćivanje pristupa postovima, stranicama, kategorijama, oznakama i više.','PublishPress'=>'PublishPress','https://publishpress.com/'=>'https://publishpress.com/','Edit Tag for All Post Types'=>'Uredi oznaku za sve tipove objava','Edit Tag for Posts'=>'Uredi oznaku za objave','Advanced Custom Fields'=>'Napredna prilagođena polja','Control front-end access to Field Groups with advanced permission management.'=>'Kontrolirajte pristup na prednjem kraju za Grupe Polja s naprednim upravljanjem dozvolama.','Control access to Field Groups'=>'Kontrolirajte pristup grupama polja','Front-end visibility restrictions'=>'Ograničenja vidljivosti na prednjem kraju','Integration with permission groups'=>'Integracija s grupama dozvola','Beaver Builder'=>'Beaver Builder','Compatibility with Edit Permissions in Beaver Builder.'=>'Kompatibilnost s uređivanjem dozvola u Beaver Builderu.','Beaver editor integration'=>'Integracija Beaver uređivača','Widget-level permission controls'=>'Kontrole dozvola na razini widgeta','Template access restrictions'=>'Ograničenja pristupa predlošku','bbPress Forums'=>'bbPress Forumi','Forum-specific permissions for bbPress with detailed control over forum access and participation.'=>'Specifične dozvole za forum za bbPress s detaljnom kontrolom pristupa i sudjelovanja na forumu.','Forum-specific permissions'=>'Dozvole specifične za forum','Topic creation restrictions'=>'Ograničenja za stvaranje tema','Forum access controls'=>'Kontrole pristupa forumu','BuddyPress'=>'BuddyPress','Assign post and term permissions to BuddyPress groups for enhanced content control.'=>'Dodijelite dozvole za postove i termine BuddyPress grupama za poboljšanu kontrolu sadržaja.','Assign post permissions to BuddyPress groups'=>'Dodijelite dopuštenja za postove BuddyPress grupama','Assign term permissions to BuddyPress groups'=>'Dodijelite dopuštenja za termine BuddyPress grupama','Group-based content permissions'=>'Dopuštenja sadržaja temeljenog na grupama','CMS Tree View'=>'CMS pregled stabla','Compatibility with Edit Permissions in CMS Tree View.'=>'Kompatibilnost s uređivanjem dopuštenja u CMS pregledu stabla.','Permission-aware tree view'=>'Pregled stabla svjestan dopuštenja','Hierarchical content controls'=>'Hijerarhijske kontrole sadržaja','Elementor'=>'Elementor','Compatibility with Edit Permissions in Elementor.'=>'Kompatibilnost s uređivanjem dopuštenja u Elementoru.','Elementor editor integration'=>'Integracija Elementor urednika','The Events Calendar'=>'Kalendar događaja','Apply permission controls to events and event-related content.'=>'Primijenite kontrole dopuštenja na događaje i sadržaj vezan uz događaje.','Event post permissions'=>'Dopuštenja za postove događaja','Event taxonomy controls'=>'Kontrole taksonomije događaja','Nested Pages'=>'Ugniježdene stranice','Compatibility with Edit Permissions in Nested Pages.'=>'Kompatibilnost s uređivanjem dopuštenja u ugniježdenim stranicama.','Permission-aware nested view'=>'Pogled s podrškom za dozvole','Quick edit integration'=>'Integracija brzog uređivanja','PublishPress Statuses'=>'PublishPress Statusi','Compatibility with PublishPress Statuses plugin.'=>'Kompatibilnost s PublishPress Statusi dodacima.','Custom status permissions'=>'Dozvole za prilagođene statuse','Workflow-specific access controls'=>'Kontrole pristupa specifične za radne tokove','Status-based editing capabilities'=>'Mogućnosti uređivanja na temelju statusa','Relevanssi'=>'Relevanssi','Filter search results based on View Permissions for secure content discovery.'=>'Filtrirajte rezultate pretraživanja na temelju Dozvola Pregleda za sigurno otkrivanje sadržaja.','Search result filtering'=>'Filtriranje rezultata pretraživanja','Permission-aware indexing'=>'Indeksiranje s podrškom za dozvole','Secure content discovery'=>'Sigurno otkrivanje sadržaja','SearchWP'=>'SearchWP','Compatibility with SearchWP term filtering for advanced search capabilities.'=>'Kompatibilnost sa SearchWP filtriranjem pojmova za napredne mogućnosti pretraživanja.','Permission-aware search results'=>'Rezultati pretraživanja s podrškom za dozvole','Term-based filtering'=>'Filtriranje na temelju pojmova','Advanced search controls'=>'Napredne kontrole pretraživanja','WooCommerce'=>'WooCommerce','Apply permission controls to WooCommerce products and product categories.'=>'Primijenite kontrole dozvola na WooCommerce proizvode i kategorije proizvoda.','Product permissions'=>'Dozvole za proizvode','Product category controls'=>'Kontrole kategorija proizvoda','WPML'=>'WPML','Multilingual support with permission synchronization across content translations.'=>'Podrška za više jezika s sinkronizacijom dozvola kroz prijevode sadržaja.','Permission synchronization across translations'=>'Usklađivanje dozvola kroz prijevode','Language-specific content access'=>'Pristup sadržaju specifičnom za jezik','Multilingual permission management'=>'Upravljanje višjezikačkim dozvolama','Yoast SEO'=>'Yoast SEO','Exclude restricted posts from XML sitemaps to maintain proper SEO indexing.'=>'Isključi ograničene objave iz XML sitemapa za održavanje pravilnog SEO indeksiranja.','Sitemap filtering for restricted content'=>'Filtriranje sitemapa za ograničeni sadržaj','Search engine visibility controls'=>'Kontrole vidljivosti za tražilice','Permission-aware XML sitemaps'=>'XML sitemapi sa sviješću o dozvolama','YooTheme'=>'YooTheme','Compatibility with YooTheme builder and term permissions.'=>'Kompatibilnost s YooTheme graditeljem i dozvolama termina.','Builder interface compatibility'=>'Kompatibilnost sučelja graditelja','Term permission integration'=>'Integracija dozvola termina','Template access controls'=>'Kontrole pristupa predlošcima','Viewing'=>'Pregledavanje','Access Circles'=>'Pristup krugovima','Editing Permissions'=>'Uređivanje dozvola','Compatibility Pack'=>'Kompatibilnost paketa','Teaser'=>'Teaser','File Access'=>'Pristup datotekama','Membership'=>'Članstvo','User Posts'=>'Objave korisnika','Visibility Circles and Editorial Circles block access to content not authored by other group members.'=>'Krugovi vidljivosti i Urednički krugovi blokiraju pristup sadržaju koji nisu napisali drugi članovi grupe.','Post-specific and category-specific permissions for creation and editing.'=>'Dozvole specifične za objavu i kategoriju za kreiranje i uređivanje.','Integration with ACF, bbPress, BuddyPress, Relevanssi, WPML and other plugins; enhanced Multisite support.'=>'Integracija s ACF, bbPress, BuddyPress, Relevanssi, WPML i drugim dodacima; poboljšana podrška za Multisite.','On the site front end, display teaser text for unreadable posts instead of hiding them.'=>'Na prednjem kraju stranice, prikažite tekst za uvid za nečitljive postove umjesto da ih skrivajte.','Restrict direct file requests based on user\'s access to the page a file is attached to.'=>'Ograničite izravne zahtjeve za datotekama na temelju pristupa korisnika stranici kojoj je datoteka pridružena.','Time-limit access customizations by delaying or expiring Permission Group membership.'=>'Prilagodbe pristupa s vremenskim ograničenjima putem odgađanja ili isteka članstva u Grupi Dozvola.','Auto-create a page for each user of specified roles. Compatible with several Team / Staff plugins.'=>'Automatski kreirajte stranicu za svakog korisnika određenih uloga. Kompatibilno s nekoliko dodataka za Tim / Osoblje.','Visibility Circles and Editorial Circles block access to content not authored by other group members. Any WP Role, BuddyPress Group or custom Group can be marked as a Circle for specified post types.'=>'Krugovi vidljivosti i Urednički krugovi blokiraju pristup sadržaju koji nisu napisali drugi članovi grupe. Svaka WP uloga, BuddyPress grupa ili prilagođena grupa može biti označena kao Krug za određene vrste postova.','Supports content-specific permissions for editing, term assignment and page parent selection. In combination with other modules, supports workflow statuses, PublishPress and PublishPress Revisions.'=>'Podržava specifične dozvole za sadržaj za uređivanje, dodjelu termina i odabir roditeljske stranice. U kombinaciji s drugim modulima, podržava status rada, PublishPress i PublishPress Revizije.','Adds compatibility or integration with ACF, bbPress, Relevanssi, CMS Tree Page View, Custom Post Type UI, Subscribe2, WPML, various other plugins. Configure any BuddyPress Group as a Permissions Group. For multisite, provides network-wide Permission Groups.'=>'Dodaje kompatibilnost ili integraciju s ACF, bbPress, Relevanssi, CMS Tree Page View, Custom Post Type UI, Subscribe2, WPML i raznim drugim dodacima. Konfigurirajte bilo koju BuddyPress grupu kao Grupu Dozvola. Za multisite, pruža Grupu Dozvola na razini mreže.','On the site front end, replace non-readable content with placeholder text. Can be enabled for any post type. Custom filters are provided but no programming is required for basic usage.'=>'Na prednjem kraju stranice, zamijenite nečitljiv sadržaj s tekstom za zamjenu. Može se omogućiti za bilo koju vrstu postova. Pruženi su prilagođeni filteri, ali nije potrebno programiranje za osnovnu upotrebu.','Filters direct file access, based on user\'s access to post(s) which the file is attached to. No additional configuration required. Creates/modifies .htaccess file in uploads folder (and in main folder for multisite).'=>'Filtrira izravni pristup datotekama, na temelju pristupa korisnika postovima na koje je datoteka pridružena. Nema dodatne konfiguracije potrebne. Kreira/modificira .htaccess datoteku u mapi za učitavanje (i u glavnoj mapi za multisite).','Allows Permission Group membership to be date-limited (delayed and/or scheduled for expiration). Simple date picker UI alongside group membership selection.'=>'Omogućuje članstvo u Grupi Dozvola da bude vremenski ograničeno (odgođeno i/ili zakazano za isteknuće). Jednostavno sučelje za odabir datuma uz odabir članstva u grupi.','Create or synchronize posts to match users. Designed for Team / Staff plugins, but with broad usage potential.'=>'Kreirajte ili sinkronizirajte postove kako biste odgovarali korisnicima. Dizajnirano za dodatke za Tim / Osoblje, ali s širokim potencijalom za korištenje.','If you like %s, please leave us a %s rating. Thank you!'=>'Ako vam se sviđa %s, molimo vas da nam ostavite %s ocjenu. Hvala vam!','About PublishPress Permissions'=>'O PublishPress Dozvolama','About'=>'O aplikaciji','Permissions Documentation'=>'Dokumentacija o dozvolama','Documentation'=>'Dokumentacija','Contact the PublishPress team'=>'Kontaktirajte tim PublishPress','Contact'=>'Kontakt','Permission Group'=>'Grupa dozvola','Specific Permissions: restrictions (\'Blocked\') take priority over additions (\'Enabled\')'=>'Specifične dozvole: ograničenja (\'Blokirano\') imaju prioritet nad dodacima (\'Omogućeno\')','Specific Permissions: no restrictions (\'Blocked\') can be applied to custom-defined groups'=>'Specifična dopuštenja: nema ograničenja (\'Blokirano\') koja se mogu primijeniti na korisnički definirane grupe','Extra Roles assignment available for {All} and {Anonymous} metagroups'=>'Dostupna dodatna dodjela uloga za metagrupe {All} i {Anonymous}','Allow the {All} and {Anonymous} metagroups to be granted specific reading permissions for private content'=>'Dopusti {All} i {Anonymous} metagrupe da im se dodijele specifična dopuštenja za čitanje privatnog sadržaja','Users who have specific editing permissions for a post or attachment can also delete it'=>'Korisnici koji imaju specifična dopuštenja za uređivanje objave ili privitka također je mogu izbrisati','Users who have custom editing permissions for an attachment can also delete it'=>'Korisnici koji imaju prilagođena dopuštenja za uređivanje privitka također ga mogu izbrisati','Disable front end filtering if logged user is a content administrator (normally filter to force inclusion of readable private posts in get_pages() listing, post counts, etc.'=>'Onemogući filtriranje na prednjem kraju ako je prijavljeni korisnik administrator sadržaja (normalno filtriraj da se prisili uključivanje čitljivih privatnih objava u get_pages() popis, broj objava itd.','Disable front end filtering for all users (subject to limitation by PP_UNFILTERED_FRONT_TYPES)'=>'Onemogući filtriranje na prednjem kraju za sve korisnike (podložno ograničenju od PP_UNFILTERED_FRONT_TYPES)','Comma-separated list of post types to limit the effect of PP_UNFILTERED_FRONT and apply_filters( \'presspermit_skip_cap_filtering\' )'=>'Popis tipova objava odvojen zarezima za ograničavanje učinka PP_UNFILTERED_FRONT i apply_filters( \'presspermit_skip_cap_filtering\' )','Specific Permissions: additions (\'Enabled\') are not applied, cannot be assigned'=>'Specifična dopuštenja: dodaci (\'Omogućeno\') se ne primjenjuju, ne mogu se dodijeliti','Don\'t assign or apply specific permissions for the \'post\' type'=>'Ne dodjeljujte ili primjenjujte specifične dozvole za tip \'post\'','Don\'t assign or apply specific permissions for the \'page\' type'=>'Ne dodjeljujte ili primjenjujte specifične dozvole za tip \'page\'','Don\'t assign or apply specific permissions for the \'media\' type'=>'Ne dodjeljujte ili primjenjujte specifične dozvole za tip \'media\'','Don\'t assign or apply specific permissions for the specified custom post type'=>'Ne dodjeljuj ili ne primjenjuj specifična dopuštenja za određeni prilagođeni tip objave','Include scheduled posts in the posts query if user can edit them'=>'Uključi zakazane objave u upit objava ako ih korisnik može uređivati','Don\'t filter term post counts in get_terms() call'=>'Ne filtriraj broj objava za pojmove u pozivu get_terms()','Leave unreadable posts on WP Navigation Menus'=>'Ostavi nečitljive objave na WP navigacijskim izbornicima','Don\'t apply CSS to hide empty Nav Menus'=>'Ne primjenjuj CSS za skrivanje praznih navigacijskih izbornika','For legacy Nav Menus, hide empty nav menu div'=>'Za naslijeđene navigacijske izbornike, sakrij prazni div navigacijskog izbornika','Leave terms with no readable posts on WP Navigation Menus'=>'Ostavi pojmove bez čitljivih objava na WP navigacijskim izbornicima','When Teaser is applied with Redirect enabled, append original url as redirect_to argument'=>'Kada se Teaser primijeni s omogućenom preusmjeravanjem, dodaj originalni URL kao argument redirect_to','For Teaser compatibility, specify a redirect argument to use instead of redirect_to'=>'Za kompatibilnost s Teaserom, navedi argument za preusmjeravanje koji će se koristiti umjesto redirect_to','For Teaser compatibility, specify an additional redirect argument other than redirect_to'=>'Za kompatibilnost s Teaserom, navedi dodatni argument za preusmjeravanje osim redirect_to','For Teaser compatibility, prevent the pp_permissions argument from being appended to redirects'=>'Za kompatibilnost s Teaserom, spriječi da se argument pp_permissions dodaje preusmjeravanjima','Filter priority for \'get_pages\' filter (default: 1)'=>'Prioritet filtriranja za \'get_pages\' filtriranje (zadano: 1)','Don\'t include readable private pages in the Pages widget or other wp_list_pages() / get_pages() results    '=>'Ne uključuj čitljive privatne stranice u widgetu Stranice ili druge wp_list_pages() / get_pages() rezultate    ','If some pages have been suppressed from get_pages() results, change child pages\' corresponding post_parent values to a visible ancestor'=>'Ako su neke stranice potisnute iz get_pages() rezultata, promijeni odgovarajuće post_parent vrijednosti podređenih stranica na vidljivog pretka','Never modify the post_parent value in the get_pages() result set, even if some pages have been suppressed'=>'Nikada ne mijenjaj post_parent vrijednost u get_pages() skupu rezultata, čak i ako su neke stranice potisnute','For performance, change the get_pages() database query to return only a subset of fields, excluding post_content'=>'Za performanse, promijeni get_pages() upit na bazi podataka da vrati samo podskup polja, isključujući post_content','Don\'t apply content teaser to get_pages() results (leave unreadable posts hidden)'=>'Ne primjenjuj sadržajni teaser na get_pages() rezultate (ostavi nečitljive objave skrivenima)','If some terms have been suppressed from get_terms() results, change child terms\' corresponding parent values to a visible ancestor'=>'Ako su neki pojmovi potisnuti iz get_terms() rezultata, promijeni odgovarajuće vrijednosti roditelja podređenih pojmova na vidljivog pretka','Never modify the parent value in the get_terms() result set, even if some terms have been suppressed'=>'Nikada ne mijenjaj roditeljsku vrijednost u get_terms() skupu rezultata, čak i ako su neki pojmovi potisnuti','Set Author to current user if autoset_post_author / autoset_page_author capability is assigned'=>'Postavi autora na trenutnog korisnika ako je dodijeljena sposobnost autoset_post_author / autoset_page_author','Leave Media Library with normal access criteria based on user\'s role capabilities '=>'Ostavi Medijsku biblioteku s normalnim kriterijima pristupa temeljenim na sposobnostima korisničkih uloga ','Accommodate front end uploading solutions that require page editing capabilities for the async upload request'=>'Prilagodi rješenja za učitavanje na prednjem kraju koja zahtijevaju mogućnosti uređivanja stranica za asinkroni zahtjev za učitavanje','Treat media attached to unregistered post types as unattached, to avoid improper and confusing filtering'=>'Tretiraj medije povezane s neprijavljenim vrstama postova kao nepovezane, kako bi se izbjeglo nepravilno i zbunjujuće filtriranje','Attached Files Private setting available'=>'Postavka privatnosti za priložene datoteke dostupna','Comma-separated list of mime types to exclude from File Access filtering'=>'Popis mime tipova odvojen zarezima koje treba isključiti iz filtriranja pristupa datotekama','Comma-separated list of mime types to include in File Access filtering (bypassing others)'=>'Popis mime tipova odvojen zarezima za uključivanje u filtriranje pristupa datotekama (zaobići druge)','When file access is blocked, do not set the WP_Query 404 / 403 property'=>'Kada je pristup datotekama blokiran, nemojte postavljati WP_Query 404 / 403 svojstvo','HTTP status code to send when file access is blocked'=>'HTTP status kod koji treba poslati kada je pristup datotekama blokiran','On Users listing, Permission groups in custom column are list filter links instead of group edit links'=>'Na popisu korisnika, grupe dopuštenja u prilagođenoj koloni su veze za filtriranje umjesto veza za uređivanje grupa','Unlock Permissions > Settings > Core > Admin Back End > \'Hide non-editable posts\''=>'Otključaj Dopuštenja > Postavke > Jezgra > Administratorsko sučelje > \'Sakrij neuredive postove\'','Within the async-upload.php script, filter author\'s retrieval of the attachment they just uploaded'=>'Unutar skripte async-upload.php, filtriraj preuzimanje autora vezanog uz privitak koji su upravo učitali','Don\'t filter comment display or moderation within wp-admin'=>'Nemojte filtrirati prikaz komentara ili moderaciju unutar wp-admin','Allow Administrators to be added to Permission Groups, even though they are not restricted'=>'Dopusti dodavanje administratora u grupe dopuštenja, iako nisu ograničeni','If propagating permissions are assigned to a page branch, overwrite any explicitly assigned permissions in sub-pages'=>'Ako su dopuštenja za propagaciju dodijeljena grani stranice, prepiši svaka izričito dodijeljena dopuštenja u podstranicama','Max number of specific permissions to insert in a single database query (default 1000)'=>'Maksimalan broj specifičnih dopuštenja za umetanje u jedan upit baze podataka (zadano 1000)','Don\'t tweak the admin menu indexes to position Permissions menu under Users'=>'Nemojte prilagođavati indekse administratorskog izbornika kako biste pozicionirali izbornik Dozvola ispod Korisnika','Don\'t add a Permissions menu. Instead, add menu items to the Users and Settings menus.'=>'Ne dodavati izbornik Dopuštenja. Umjesto toga, dodajte stavke izbornika u izbornike Korisnici i Postavke.','Customize Permissions screen title for Groups'=>'Prilagodite naslov zaslona Dozvola za Grupe','Customize Permission Groups caption on user profile'=>'Prilagodite natpis Grupa dozvola na profilu korisnika','Only one group is selectable on Add User screen'=>'Samo jedna grupa se može odabrati na ekranu Dodaj korisnika','Only one group is selectable on Edit User screen'=>'Samo jedna grupa se može odabrati na ekranu Uredi korisnika','Display a custom hint on Permissions > User Groups'=>'Prikaži prilagođeni savjet o Dozvolama > Korisničke grupe','Max number of non-hierarchical posts / terms to display at one time (per page)'=>'Maksimalan broj ne-hijerarhijskih postova / pojmova koji se prikazuju u jednom trenutku (po stranici)','Max number of hierarchical posts / terms to display at one time (per page)'=>'Maksimalni broj hijerarhijskih objava / pojmova koji se prikazuju u jednom trenutku (po stranici)','Disable auto-determination of how many levels of page tree to make visble by default. Instead, use specified value.'=>'Onemogući automatsko određivanje koliko razina stabla stranica će biti vidljivo prema zadanim postavkama. Umjesto toga, koristi zadanu vrijednost.','Target number of visible pages/terms, used for auto-determination of number of visible levels'=>'Ciljani broj vidljivih stranica/pojmovâ, koristi se za automatsko određivanje broja vidljivih razina','Make search function on the post selection metabox look at post content'=>'Omogući funkciju pretraživanja u metaboxu odabira objava da gleda sadržaj objave','Make search function on the post selection metabox look at post excerpt'=>'Omogući funkciju pretraživanja u metaboxu odabira objava da gleda izvadak objave','Search by last name instead of display name'=>'Pretraživanje prema prezimenu umjesto prema prikazanom imenu','User field to search by default'=>'Korisničko polje za pretraživanje prema zadanim postavkama','User meta fields selectable for search (comma-separated)'=>'Korisnička meta polja koja se mogu odabrati za pretraživanje (odvojena zarezom)','User meta fields which should be treated as numeric (comma-separated)'=>'Korisnička meta polja koja bi se trebala tretirati kao numerička (odvojena zarezom)','User meta fields which should be treated as boolean (comma-separated)'=>'Korisnička meta polja koja bi se trebala tretirati kao boolean (odvojena zarezom)','Use display name for search results instead of user_login'=>'Koristi prikazano ime za rezultate pretraživanja umjesto user_login','When synchronizing role metagroups to currently defined WP roles, don\'t delete groups for previously defined WP roles.'=>'Prilikom sinkronizacije metagruppa uloga s trenutno definiranim WP ulogama, ne briši grupe za prethodno definirane WP uloge.','Force detection of WP user roles which are appended dynamically but not stored to the WP database.'=>'Primoraj detekciju WP korisničkih uloga koje se dinamički dodaju ali nisu pohranjene u WP bazu podataka.','To save memory on front end access, don\'t register any filters related to content editing'=>'Da bi se uštedjela memorija na pristupu prednjem kraju, ne registriraj nikakve filtre povezane s uređivanjem sadržaja','Attached media do not have any comments, so don\'t append clauses to comment queries for them'=>'Priloženi mediji nemaju nikakve komentare, stoga ne dodavati klauzule u upite za komentare za njih','Reduce overhead of pages query (in get_pages() and wp-admin) by defaulting fields to a set list that does not include post_content '=>'Smanji preopterećenje upita za stranice (u get_pages() i wp-admin) postavljanjem polja na zadani popis koji ne uključuje post_content ','Reduce overhead of wp-admin posts query by defaulting fields to a set list that does not include post_content '=>'Smanjite opterećenje wp-admin upita za postove postavljanjem polja na unaprijed definirani popis koji ne uključuje post_content','Reduce overhead of wp-admin Media query by defaulting fields to a set list that does not include post_content '=>'Smanjite opterećenje wp-admin upita za Medije postavljanjem polja na unaprijed definirani popis koji ne uključuje post_content','Reduce overhead of wp-admin query for specified custom post type by defaulting fields to a set list that does not include post_content '=>'Smanjite opterećenje wp-admin upita za određenu prilagođenu vrstu posta postavljanjem polja na unaprijed definirani popis koji ne uključuje post_content','Work around database setup warnings (at plugin activation) on some servers'=>'Zaobiđite upozorenja o postavkama baze podataka (prilikom aktivacije dodatka) na nekim poslužiteljima','Development use only (suppresses post_status = \'publish\' clause for unfiltered post types with anonymous user)'=>'Samo za razvojne svrhe (ukida post_status = \'publish\' uvjet za nefiltrirane vrste postova s anonimnim korisnikom)','Development use only (on front end, do not replace \'post_status = \'publish\'\' clause with filtered equivalent)'=>'Samo za razvojne svrhe (na prednjem kraju, nemojte zamijeniti \'post_status = \'publish\'\' uvjet s filtriranim ekvivalentom)','Logged In'=>'Prijavljen','Not Logged In'=>'Nije prijavljen','Everyone'=>'Svi','